# Fusionamos todas las preguntas eliminando duplicados por enunciado normalizado
todas = []
vistos = set()

def normalizar(txt):
    return re.sub(r'\W+', '', txt.lower())

for q in snippet1 + snippet2 + snippet3_4:
    norm = normalizar(q["enunciado"])
    if norm not in vistos:
        vistos.add(norm)
        todas.append(q)

print(f"Total de preguntas unificadas sin duplicados: {len(todas)}")

# Asignamos ID numérico secuencial a todas las preguntas
for idx, q in enumerate(todas):
    q["id"] = idx + 1

# Guardamos el json compilado para integrarlo en data.js
with open("compiled_questions.json", "w", encoding="utf-8") as f:
    json.dump(todas, f, ensure_ascii=False, indent=2)

print("Compilado guardado exitosamente en compiled_questions.json")
